from functools import lru_cache
from math import log2, pow

def max_power_of_2(n):
    return log2(n)

def is_palindrome(s):
    return s == s[::-1]

@lru_cache(maxsize=None)
def count_palindromes(n):
    if n == 0:
        return 1
    if n == 1:
        return 1
    return pow(2, max_power_of_2(n) - n + 1) * 2 % 998244353

def solve(s):
    mod = 998244353
    s = s[1:]
    m = len(s)
    if m == 1:
        return count_palindromes(1)

    total_pairs = 0

    for i in range(m):
        if i < m // 2:
            pairs = count_palindromes(m - i - 1) * count_palindromes(i) % mod
        else:
            pairs = count_palindromes(i)
        if s[i] == '0':
            pairs *= 2
        elif s[i] == '1':
            pairs *= 4

        total_pairs += pairs

    return total_pairs % mod

