To solve this problem, we need to find the minimal cost to separate the cities into two equal groups by destroying the minimum cost of the roads. This can be achieved using a union-find data structure to keep track of the connected components and then calculating the cost of destroying the roads within each component.

Here's a Python program to achieve this:

```python
import sys
from dataclasses import dataclass

@dataclass
class Edge:
    u: int
    v: int
    weight: int

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, u):
        if u != self.parent[u]:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

    def union(self, u, v):
        root_u = self.find(u)
        root_v = self.find(v)
        if root_u == root_v:
            return
        if self.rank[root_u] > self.rank[root_v]:
            self.parent[root_v] = root_u
        elif self.rank[root_v] > self.rank[root_u]:
            self.parent[root_u] = root_v
        else:
            self.parent[root_v] = root_u
            self.rank[root_u] += 1

def calculate_min_cost(edges):
    uf = UnionFind(len(edges))
    cost = 0
    for u, v, weight in edges:
        root_u = uf.find(u)
        root_v = uf.find(v)
        if root_u != root_v:
            uf.union(u, v)
            cost += weight
    return cost // 2

if __name__ == "__main__":
    N, M = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]
    print(calculate_min_cost(edges))
