import sys
import heapq

# Function to find the minimum cost to split the cities into two equal groups
def minimizedCostPartition(N, M, roads):
    cost_map = {i: [] for i in range(N//2 + N % 2)}
    for a, b, c in roads:
        cost_map[a].append(c)
        cost_map[b].append(c)

    first_group, second_group = [], []
    for i in range(N):
        if len(cost_map[i]) % 2 == 1:
            first_group.append(i)
        else:
            heapq.heappush(second_group, (cost_map[i][0], i))

    min_cost = float('inf')
    pairs = 0
    while pairs < len(first_group):
        if not second_group:
            min_cost = min(min_cost, first_group.pop()[0])
        else:
            cost, city = heapq.heappop(second_group)
            cost = -cost  # Convert to increase priority for splitting conditions
            removed_city = -cost_map[city][0]
            cost_map[city].pop(0)
            if len(cost_map[city]) == 0:
                del cost_map[city]
            min_cost = min(min_cost, sum(cost_map[city]) + removed_city)
            min_cost = min(min_cost, cost + removed_city)
            if len(cost_map[city]) > 0:
                heapq.heappush(second_group, (cost_map[city][0], -cost_map[city[0]]))
                cost_map[-cost_map[city[0]]] = []

    return [min_cost] * (N//2)

# Read input
