import math

MOD = 100000000000007

def catalan_number(n):
    result = 1
    for i in range(n):
        result = (result * (2 * i + 1) // (i + 1)) % MOD
    return result

def count_games(N, K):
    if N <= 1:
        return 1

    if K == 0:
        return 0

    if N == 2:
        return 1

    dp = [0] * (N + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, N + 1):
        dp[i] = dp[i - 1] * i % MOD

    if N <= 2:
        return dp[N] * (1 + catalan_number(K)) % MOD

    count = 0

    for k in range(K + 1):
        count = (count + dp[k] * catalan_number(N - k) * eval('3 ** ' + str(k * (N - k) - 1))) % MOD

    return count * (1 + catalan_number(K)) % MOD

