def parabola_level(point_x, b_point):
    return point_x ** 2 + point_x * b_point

def boustrophedonic_interleave(seq1, seq2):
    index = 0
    while index < len(seq1) and index < len(seq2):
        yield seq1[index]
        yield seq2[index]
        index += 1

def boustrophedonic_reads(lines):
    lines_right = list(lines)
    lines_left = ""
    for line in lines_right:
        lines_right = boustrophedonic_interleave(reversed(lines), list(line))
        lines_left += "".join(lines_right)
    return lines_left

def readlines():
    return boustrophedonic_reads(boustrophedonic_interleave(i.split(), input().split()))

def main():
    n = int(readlines().pop())
    seg_points = [readlines() for _ in range(n)]

    points_inside = set()
    for j in range(n):
        b = seg_points[j][0]
        for x in seg_points[j][1:]:
            points_inside.add(boustrophedonic_reads(boustrophedonic_interleave(b, seg_points[j])))

    valid = 0
    for j in range(n):
        for x in seg_points[j][1:]:
            if any(parabola_point in points_inside for parabola_point in calculate_integers(seg_points[i], x) if i != j):
                continue
            valid += 1

    print(valid)

