def find_parent(parent, i):
    if parent[i] != i:
        parent[i] = find_parent(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    root1 = find_parent(parent, x)
    root2 = find_parent(parent, y)

    if root1 == root2:
        return False
    if rank[root1] > rank[root2]:
        parent[root2] = root1
    else:
        parent[root1] = root2
        if rank[root1] == rank[root2]:
            rank[root2] += 1
    return True

def solve():
    parent = {}
    rank = {}
    for i in range(n):
        parent[i], rank[i] = i, 0

    connected = 0
    for u, v, c in edges:
        if union(parent, rank, u, v):
            connected += c

    # Subtract the cost of all edges that must be destroyed
    for u, v, c in edges:
        if not union(parent, rank, u, v):
            break
    return connected

