import queue
import sys

def calculate_cost(links, k):
    total_cost = 0
    total_bandwidth = 0

    for link in links:
        total_cost += k * k / link[3] * link[3]
        total_bandwidth += link[3]

    return total_cost, total_bandwidth

def is_optimal(link):
    for i in range(2, len(link) - 1):
        if link[0] != 1 and link[0] == link[1 + i]:
            return True
    return False

def find_link(index, nodes, remaining_links):
    queue = []
    selected_links = []

    for i in range(2, len(nodes)):
        if len(remaining_links[i]) > 0:
            queue.append(i)

    while queue:
        i = queue.popleft()
        selected_links.append(i)

        if len(selected_links) == index + 1:
            if index < i - 2:
                return False
            selected_links.append(nodes[i - 2][0] if i - 2 >= 2 else 0)
            for j in range(index + 1, len(selected_links)):
                queue.append(selected_links[j])

    return True

def solve(remaining_links, start_node, end_node, k):
    if len(remaining_links) == 0:
        return calculate_cost(remaining_links, k)

    if is_optimal(remaining_links):
        return k, k

    next_node = None
    next_link = -1

    for node in remaining_links:
        if sum(node) > remaining_links[node][2] * k:
            next_node = node[1]
            next_link = node[0]

    if next_node is None:
        return calculate_cost(remaining_links, k)

    cost, bandwidth = solve_remaining_links(next_link, next_node, remaining_links, start_node, end_node, k)

    for node in remaining_links:
        if sum(node) >= sum(cost) + 1e-6:
            cost.append([k, node[0]])
            bandwidth += node[2]

    return cost, bandwidth

def calculate_cost_remaining_links(remaining_links, start_node, end_node):
    cost, bandwidth = 0, 0
    for link in remaining_links:
        if link in remaining_links[start_node - 1]:
            cost += k * k / link[3] * link[3]
        else:
            cost += k * k / link[3] * link[3] * (link[3] - 1)

        bandwidth += link[3]

    return cost, bandwidth

def solve_remaining_links(next_link, next_node, remaining_links, start_node, end_node, k):
    remaining_links[next_node - 1].append(next_link)
    remaining_links[0].append([-1, next_node])

    if next_node == end_node:
        return calculate_cost_remaining_links(remaining_links, next_node, end_node)

    cost, bandwidth = calculate_cost_remaining_links(remaining_links[next_node - 1], next_node, next_node - 1, k)

    for link in remaining_links[next_node - 1]:
        remaining_links[0].append(link)

    return cost, bandwidth

