def subtree_size(tree, root):
    stack = [root]
    visited = {root: 0}
    while stack:
        node = stack.pop()
        for neighbor in tree[node]:
            if neighbor in visited:
                continue
            visited[neighbor] = visited[node] + 1
            stack.append(neighbor)

    return visited

def csi_calculator(tree, root, subtree_sizes, operations):
