    for a, b in operations:
        prefix_tree = defaultdict(lambda: defaultdict(int))
        a_size = subtree_sizes[a]
        b_size = subtree_sizes[b]

        for node in range(1, a_size + 1):
            prefix_tree[tree[node]][node] += 1

        for node in range(1, b_size + 1):
            total_counts[b_size + 1] += prefix_tree[tree[node]][node]
            for i in range(1, b_size + 1):
                if i < node:
