import sys
import heapq

def readfile(filename):
    with open(filename, 'r') as file:
        n, m = map(int, file.readline().strip().split())
        links = {}
        for _ in range(m):
            f, t, w, b = map(int, file.readline().strip().split())
            links[(f, t)] = (w, b)
            links[(t, f)] = (w, b)

    return n, links

def find_optimal_connections(n, links):
    nodes = list(range(1, n + 1))

    # Build a graph with node indices as keys
    graph = {node: [] for node in nodes}
    for f, t, _, _ in links.values():
        graph[f].append(t)
        graph[t].append(f)

    # Prune heavy graphs
    remaining_nodes = len(nodes)
    while remaining_nodes < n - 2:
        links_to_prune = []
        for f in graph.keys():
            for t in graph[f]:
                # Calculate the shortest path length
                path_length = 0
                current_node = t
                while current_node != f:
                    path_length += links[(f, current_node)][1]
                    # Allowing weighted links themselves to be used
                    if path_length > remaining_nodes:
                        links_to_prune.append((f, t))
                        break
                    current_node = graph[current_node][0]
        for f, t in links_to_prune:
            graph[f].remove(t)
            graph[t].remove(f)

    optimal_value = 'UNKNOWN'
    if remaining_nodes == n - 2:
        costs = [float('inf')] * len(nodes)
        dist = {node: float('inf') for node in nodes}
        queue = [(0, 1)]
        while queue:
            cost, node = heapq.heappop(queue)
            if cost > costs[node - 1]:
                continue
            if node == n:
                optimal_value = node
            for neighbor in graph[node]:
                if dist[neighbor] > cost + links[(node, neighbor)][1]:
                    dist[neighbor] = cost + links[(node, neighbor)][1]
                    heapq.heappush(queue, (cost + links[(node, neighbor)][1], neighbor))
        total_cost = sum(cost * cost for cost in dist.values())
        total_bandwidth = sum(links[connection] for connection in cost_to_bandwidth)
        efficiency = round(total_cost / total_bandwidth, 2)
        optimal_value = efficiency
    return str(optimal_value) if optimal_value != 'UNKNOWN' else 'BAD ' + str(links_to_prune[0])

if __name__ == "__main__":
    n, m = readfile(sys.argv[1])
    print(find_optimal_connections(n, m))
