def count_palindromic_sums(s):
    n = len(s)
    count = 0
    mod = 998244353

    for i in range(n // 2 - 1, -1, -1):
        start = int(s[i])
        end = start
        while i + 1 < n:
            if s[i] != s[i + 1]:
                end += int(s[i])
            i += 1

        if ((i - 1) % 2 == 0):
            i -= 1

        for j in range(end, end + 1 << i, 2):
            if i + 1 < 2 * i:
                if y(i + 1, i + 2 - j, s):
                    continue
                if x(i, i + 1 - y(i + 1, i + 2 - j, s)):
                    count += 1

    return count

def helper(index, acc, s):
    if index >= len(s):
        return int(acc)
    ans = 0
    if s[index] != '?':
        ans += helper(index + 1, acc + s[index], s)
        ans -= helper(index + 1, acc, s)
        if index < len(s) - 1 and s[index] == '?' and s[index + 1] == '0' or s[index] == '0' and s[index + 1] == '?':
            ans += helper(index + 1, acc + '0', s)

    if s[index] != '?':
        ans += helper(index + 1, acc + s[index], s) % mod
    return ans

def x(start, end, s):
    count = 0
    if start == end and s[start] == '1':
        count = 1
        if start < len(s) - 1 and start + 1 < len(s) and s[start] == '1' and s[start + 1] == '1':
            count += 1
    if s[start] != '?' and s[start + 1] == '?' or s[start] == '?' and s[start + 1] != '?':
        count += helper(start + 1, '', s) % mod
    return count * (end - start + 1) % mod

def y(start, end, s):
    res = 0
    for i in range(start, end + 1):
        if s[i] == '?' or s[i] == '1':
            continue
        res += abs((2 * i + start * 2 - i - 1) % len(s) - (end + start + 1))
    if res < 0:
        res += len(s)
    return min(res, len(s) - res) % mod

