from typing import List

def min_diff_movements(presents: List[List[int]]) -> int:
    presents.sort()
    n, m = len(presents), len(presents[0])
    min_diff = float('inf')
    movements = []

    def backtrack(sub_presents: List[List[int]], from_box: int, to_box: int) -> None:
        nonlocal min_diff
        if len(sub_presents) == n:
            diff = max(sub_presents) - min(sub_presents)
            if diff < min_diff:
                min_diff = diff
                movements = [[s, from_box, to_box] for s in sub_presents]
                return
        else:
            for half in range(len(sub_presents) // 2):
                for i in range(n):
                    if not (i in sub_presents[half:half+1]):
                        sub_presents.append(presents[i])
                        from_box_, to_box_ = from_box + half, to_box + half
                        if from_box_ >= n or to_box_ >= n:
                            break
                        backtrack(sub_presents, from_box_, to_box_)
                        sub_presents.pop()

    backtrack([], -1, -1)
    return min_diff, movements

# Example usage
